export async function fetchSurveysByType(type: "hskm" | "hspak"): Promise<Survey[]> {
  try {
    const query = `survey_type=eq.${type}&order=year.desc,created_at.desc`;
    const data = await supabaseFetch("surveys", query);
    if (data && Array.isArray(data) && data.length > 0) {
      return data as Survey[];
    }
  } catch (error) {
    console.warn("supabaseFetch failed for surveys, using fallback:", error);
  }
  return DEFAULT_SURVEYS.filter((s) => s.survey_type === type);
}

export async function fetchAllSurveys(): Promise<Survey[]> {
  try {
    const data = await supabaseFetch("surveys", "order=year.desc,created_at.desc");
    if (data && Array.isArray(data) && data.length > 0) {
      return data as Survey[];
    }
  } catch (error) {
    console.warn("supabaseFetch failed for all surveys, using fallback:", error);
  }
  return DEFAULT_SURVEYS;
}
